// Clamp: ensure value stays within [min, max]
public static double clamp(double value, double min, double max) {
    if (min > max) throw new IllegalArgumentException("min must be <= max");
    return Math.max(min, Math.min(value, max));
}
// clamp(150, 0, 100) = 100
// clamp(-5, 0, 100)  = 0
// clamp(42, 0, 100)  = 42

// Linear interpolation: map value from [srcMin, srcMax] to [dstMin, dstMax]
public static double mapRange(double value, double srcMin, double srcMax,
                               double dstMin, double dstMax) {
    if (srcMax == srcMin) throw new ArithmeticException("Source range cannot be zero");
    double normalised = (value - srcMin) / (srcMax - srcMin); // [0.0, 1.0]
    return dstMin + normalised * (dstMax - dstMin);
}
// mapRange(5, 0, 10, 0, 100) = 50.0
// mapRange(0.5, 0, 1, -1, 1) = 0.0

// Formula: Area = (√3 / 4) × side²
// Derivation: height h = side × sin(60°) = side × (√3/2)
//             Area = (1/2) × base × height = (1/2) × side × side×(√3/2) = (√3/4)×side²

double side = 10.0;
double area = (Math.sqrt(3) / 4) * Math.pow(side, 2);
System.out.printf("Area of equilateral triangle (side=10): %.4f%n", area);
// Output: 43.3013

// Alternative using trig:
double areaViaTrig = 0.5 * side * side * Math.sin(Math.toRadians(60));
System.out.printf("Via trig: %.4f%n", areaViaTrig); // Same: 43.3013

// Both produce the same result since sin(60°) = √3/2

